"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { listConnections } from "@/lib/api";
import { isLoggedIn } from "@/lib/auth";
import AppHeader from "@/components/AppHeader";
import GradientOrbs from "@/components/GradientOrbs";
import TiltCard from "@/components/TiltCard";
import Magnetic from "@/components/Magnetic";
import { SkeletonCard } from "@/components/ui/Skeleton";

type Connection = {
  id: number;
  nickname: string;
  engine_type: string;
  host: string;
  database_name: string;
};

export default function HomePage() {
  const [connections, setConnections] = useState<Connection[]>([]);
  const [loading, setLoading] = useState(true);
  const router = useRouter();

  useEffect(() => {
    if (!isLoggedIn()) {
      router.push("/login");
      return;
    }
    listConnections()
      .then(setConnections)
      .finally(() => setLoading(false));
  }, [router]);

  return (
    <main className="relative min-h-screen bg-graphite">
      <GradientOrbs />
      <AppHeader />

      <div className="relative z-10 mx-auto max-w-5xl px-6 py-14">
        <div className="animate-fade-in-up mb-10 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="mb-1 font-mono text-xs uppercase tracking-[0.3em] text-gold">Home</p>
            <h1 className="font-display text-4xl font-extrabold text-ink">Your databases</h1>
          </div>
          <Magnetic strength={25}>
            <Link
              href="/connect"
              className="inline-flex items-center gap-2 rounded-2xl bg-gradient-to-r from-gold to-violet px-6 py-3 font-display font-bold text-graphite shadow-[0_15px_40px_-12px_rgba(139,92,246,0.5)] transition-transform duration-200 hover:-translate-y-0.5 active:scale-95"
            >
              + Connect a database
            </Link>
          </Magnetic>
        </div>

        {loading ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            <SkeletonCard />
            <SkeletonCard />
          </div>
        ) : connections.length === 0 ? (
          <div className="animate-fade-in-up stagger-1 flex flex-col items-center gap-4 rounded-3xl border border-dashed border-white/15 bg-surface/40 px-8 py-20 text-center backdrop-blur-md">
            <span className="flex h-16 w-16 items-center justify-center rounded-2xl bg-gradient-to-br from-gold/20 to-violet/20 text-3xl">
              ⛁
            </span>
            <p className="font-display text-xl font-bold text-ink">No databases yet</p>
            <p className="max-w-sm text-mist">
              Connect your first Postgres or MySQL database to start asking questions in plain English.
            </p>
            <Link
              href="/connect"
              className="mt-2 rounded-full bg-white/5 px-5 py-2.5 text-sm font-semibold text-ink transition hover:bg-white/10"
            >
              Connect now →
            </Link>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
            {connections.map((conn, i) => (
              <div
                key={conn.id}
                className="animate-fade-in-up"
                style={{ animationDelay: `${0.08 * i}s` }}
              >
                <TiltCard>
                  <Link
                    href={`/ask?connection_id=${conn.id}`}
                    className="group relative block overflow-hidden rounded-3xl border border-white/10 bg-surface/60 p-6 backdrop-blur-xl transition-colors duration-300 hover:border-gold/30"
                  >
                    <div className="absolute -right-10 -top-10 h-32 w-32 rounded-full bg-violet/10 blur-3xl transition-all duration-500 group-hover:bg-gold/20" />
                    <div className="relative flex items-start justify-between">
                      <div>
                        <p className="font-display text-xl font-bold text-ink group-hover:text-gold transition-colors">
                          {conn.nickname}
                        </p>
                        <p className="mt-1 font-mono text-sm text-mist">
                          {conn.host} / {conn.database_name}
                        </p>
                      </div>
                      <span className="rounded-full border border-white/10 bg-white/5 px-3 py-1 font-mono text-[10px] uppercase tracking-wide text-mist">
                        {conn.engine_type}
                      </span>
                    </div>
                    <div className="relative mt-6 flex items-center gap-1.5 text-sm font-medium text-gold opacity-0 transition-opacity duration-300 group-hover:opacity-100">
                      Ask a question <span className="transition-transform group-hover:translate-x-1">→</span>
                    </div>
                  </Link>
                </TiltCard>
              </div>
            ))}
          </div>
        )}
      </div>
    </main>
  );
}
